CREATE SET TABLE MDP01_META.META_ETL_JOB_RUN ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      etl_job_run_id BIGINT NOT NULL GENERATED ALWAYS AS IDENTITY           (START WITH 1             INCREMENT BY 1             MINVALUE -999999999999999999             MAXVALUE 999999999999999999             NO CYCLE),      etl_job_id INTEGER NOT NULL,      run_timestamp TIMESTAMP(6) NOT NULL,      start_time TIMESTAMP(6) NOT NULL,      end_time TIMESTAMP(6),      duration_seconds DECIMAL(18,3),      status VARCHAR(20) CHARACTER SET LATIN CASESPECIFIC NOT NULL,      exit_code INTEGER,      rows_read DECIMAL(18,0),      rows_inserted DECIMAL(18,0),      rows_updated DECIMAL(18,0),      rows_deleted DECIMAL(18,0),      rows_rejected DECIMAL(18,0),      error_message VARCHAR(4000) CHARACTER SET LATIN CASESPECIFIC,      error_stack CLOB(16777216) CHARACTER SET UNICODE,      execution_user VARCHAR(200) CHARACTER SET LATIN CASESPECIFIC DEFAULT USER ,      execution_host VARCHAR(128) CHARACTER SET LATIN CASESPECIFIC,      execution_mode VARCHAR(50) CHARACTER SET LATIN CASESPECIFIC,      parent_run_id BIGINT,      retry_attempt INTEGER DEFAULT 0 ,      create_timestamp TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      control_flag VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC,      paused_at_step INTEGER)PRIMARY INDEX ( etl_job_run_id );